// tools/packs/stones-river.mjs: the curated source of the Stones River battle pack (assets/packs/stones-river.json is
// generated from this by `node tools/build-packs.mjs stones-river`; never edit the JSON by hand).
//
// Provenance words (AGENTS.md section 3): Verified = two independent sources agree; Inferred = one source;
// Disputed = sources disagree (both given); Estimated = arithmetic or a game value, method shown.
// Research packets (2026-10-11 session): per-phase order of battle, times and events (SR1 dawn attack, SR2 Slaughter
// Pen, SR3 Round Forest with the McFadden's Ford packet inside it), gap-fill strengths, guns and arms (SR1..SR3 fill),
// and landmark coordinates (OSM/HMDB/NPS points). The McFadden's Ford phase had no gap-fill: its Union strengths are
// Estimated here from the regimental and brigade figures in the research (methods on each unit), and the frozen old
// repo's phase-2 figures (4,000 for Beatty's division, 2,600 for Negley's counterattack) were NOT carried because the
// research found them unsourced. Citations are carried on each formation; numbers are copied from the gap-fill files
// unless a comment or status says otherwise.
//
// Positions: { lat, lon } or { near: landmark, bearing: compass degrees (0 = north, 90 = east), m: metres }.
// `bearing` on a unit is the compass direction its line faces. Every unit position is Inferred: the sources place
// units relative to roads, fields, houses and the river, never by survey, and several 1862 sites (the Cowan, Harding,
// Hoover, Gresham and Widow Smith houses) have no coordinates. The terrain asset's south edge is at 35.8496 N, about
// 400 m north of the Gresham Lane - Franklin Road junction where the dawn attack began, so the dawn-on-the-right
// phase is drawn about 600-800 m north of the sourced ground (said in its positionsNote). Opening positions are where
// each formation stood or formed at the phase's start; the player redeploys freely.
//
// Game choices (not history): clockRatio, men per figure (computed by build-packs), xp tiers, battery crews of 20 per
// gun where no crew is sourced, AI roles, reinforcement entry points, objective circles, the oval shapes of the woods.
// The engine has no cavalry, so Wharton's 2,000 cavalry (Hardee, OR p. 773) is not fielded in the dawn phase.

// ---- sources --------------------------------------------------------------------------------------------------
const OR_URL = 'https://archive.org/details/in.ernet.dli.2015.171314';
const OR = (what) => `Official Records Ser. I Vol. XX Pt. 1, ${what} (archive.org OCR scan; page numbers from OCR headers): ${OR_URL}`;
const CWS = (sec, what = '') => `Cozzens, The Battle of Stones River, NPS Civil War Series 23, sec${sec}${what ? ` (${what})` : ''}: https://npshistory.com/publications/civil_war_series/23/sec${sec}.htm`;
const BEARSS = (what = '') => `Bearss, Union Artillery and Breckinridge's Attack (NPS 1959)${what ? ` (${what})` : ''}: https://npshistory.com/publications/stri/union-artillery-breckinridge-attack.pdf`;
const WIKI_US = 'Wikipedia, Stones River Union order of battle (OR-derived; not independent of the OR): https://en.wikipedia.org/wiki/Stones_River_Union_order_of_battle';
const WIKI_CS = 'Wikipedia, Stones River Confederate order of battle (OR-derived; not independent of the OR): https://en.wikipedia.org/wiki/Stones_River_Confederate_order_of_battle';
const ABT_DAWN = 'American Battlefield Trust, "I Will Die Right Here" (dawn attack times): https://www.battlefields.org/learn/articles/i-will-die-right-here';
const ABT_SR = 'American Battlefield Trust, Stones River: https://www.battlefields.org/learn/civil-war/battles/stones-river';
const ABT_HAZEN = 'American Battlefield Trust, The secret life of the Hazen Brigade Monument (409 casualties, 29% of those engaged): https://www.battlefields.org/learn/articles/secret-life-hazen-brigade-monument';
const NPS_STOP2 = 'NPS Stones River Tour Stop 2, The Slaughter Pen: https://www.nps.gov/stri/learn/photosmultimedia/battle_stop2.htm';
const NPS_HHA = 'NPS Stones River, Hell\'s Half Acre: https://www.nps.gov/stri/learn/historyculture/hellshalfacre.htm';
const MASTERS = 'Dan Masters, Shoulder Arms! (transcription of the 15 Dec 1862 ordnance report of Sheridan\'s division, Bragg Papers; secondary): https://dan-masters-civil-war.blogspot.com/2021/10/';
const PHISTERER = 'Phisterer, The Regular Brigade of the Fourteenth Army Corps in the Battle of Stone River: https://www.gutenberg.org/files/32073';
const WAYSIDE = 'NPS "Hazen\'s Artillery" wayside text (hmdb.org m=168545, reproduced on usa-civil-war.com Stones River p.3; the marker is removed): https://www.hmdb.org/m.asp?m=168545';
const LINCOLN = 'https://quod.lib.umich.edu/l/lincoln/lincoln6/1:661?rgn=div1;view=fulltext';
const GAME_CREW = 'Battery crew: game value of 20 men per gun (no sourced crew strength)';

// ---- provenance phrases used in unit status lines ---------------------------------------------------------------
const XP_SR = 'xp 2 (trained): game rule for both armies at Stones River, which had fought at Shiloh or Perryville in 1862; brigade-level service history was not researched';
const WPN_US = 'weapon rifled: UNSOURCED low-confidence default (an uncited forum claim that about 40% of Rosecrans\'s infantry still carried smoothbores; no ordnance return for this brigade)';
const WPN_CS = 'weapon smooth: UNSOURCED low-confidence default (an uncited forum claim that about 60% of Bragg\'s infantry carried smoothbores; no ordnance return for this brigade)';
const POS = (why) => `position Inferred: ${why}`;
const status = (...parts) => parts.join('; ') + '.';
const FRANCHISE = (why) => `franchise lineage: ${why}`;

// ---- landmarks (WGS84; landmark research 2026-10-11) ------------------------------------------------------------
